<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Customer,PaymentReceived,PaymentAllocation,SalesInvoice}; use App\Services\{AuthorizationService,SalesDocumentService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class PaymentController {
 private function tenant():string{return app(TenantContext::class)->id();}
 private function authorize(Request $r):void{abort_unless($r->user()&&app(AuthorizationService::class)->allows($r->user(),$this->tenant(),'sales.manage'),403);}
 public function index(Request $r){$this->authorize($r);$q=PaymentReceived::where('tenant_id',$this->tenant())->with(['customer','allocations.invoice'])->latest('created_at');if($r->filled('customer_id'))$q->where('customer_id',$r->string('customer_id'));if($r->filled('state'))$q->where('state',$r->string('state'));if($r->filled('method'))$q->where('method',$r->string('method'));if($r->filled('search'))$q->where(fn($x)=>$x->where('reference','ilike','%'.$r->string('search').'%')->orWhereHas('customer',fn($c)=>$c->where('name','ilike','%'.$r->string('search').'%')));if($r->filled('invoice_id'))$q->whereHas('allocations',fn($a)=>$a->where('invoice_id',$r->string('invoice_id')));if($r->filled('date_from'))$q->whereDate('created_at','>=',$r->date('date_from'));if($r->filled('date_to'))$q->whereDate('created_at','<=',$r->date('date_to'));return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]);}
 public function summary(Request $r){$this->authorize($r);$q=PaymentReceived::where('tenant_id',$this->tenant());return response()->json(['data'=>['total'=>(clone $q)->count(),'pending'=>(clone $q)->where('state','pending_verification')->count(),'verified'=>(clone $q)->where('state','verified')->count(),'allocated'=>(clone $q)->whereHas('allocations')->count(),'amount'=>(string)(clone $q)->whereIn('state',['verified','reversed'])->sum('amount')]]);}
 public function store(Request $r,AuthorizationService $a){$this->authorize($r);$t=$this->tenant();$d=$r->validate(['customer_id'=>'required|uuid','reference'=>'required|string|max:100','method'=>'required|string|max:40','amount'=>['required','regex:/^\d+(\.\d{1,6})?$/','gt:0']]);abort_unless(Customer::where('tenant_id',$t)->whereKey($d['customer_id'])->exists(),404);$existing=PaymentReceived::where('tenant_id',$t)->where('reference',$d['reference'])->first();if($existing){abort_unless($existing->customer_id===$d['customer_id']&&Decimal::compare((string)$existing->amount,(string)$d['amount'])===0,422,'Payment reference already exists with different details.');return response()->json(['data'=>$existing->load('allocations')]);}return response()->json(['data'=>PaymentReceived::create([...$d,'amount'=>Decimal::normalize((string)$d['amount']),'tenant_id'=>$t,'received_by'=>$r->user()->id,'state'=>'pending_verification'])],201);}
 public function verify(Request $r,PaymentReceived $payment,SalesDocumentService $state){$this->authorize($r);$this->own($payment);abort_unless($payment->state==='pending_verification',422,'Only pending payments may be verified.');$state->transition($payment,'payment','verified',$r->user()->id);$payment->update(['verified_at'=>now(),'verified_by'=>$r->user()->id]);event(new \App\Events\PaymentVerifiedForAccounting($payment->tenant_id,$payment->id,$payment->customer_id,(string)$payment->amount));return response()->json(['data'=>$payment->fresh()]);}
 public function allocate(Request $r,PaymentReceived $payment){$this->authorize($r);$this->own($payment);abort_unless($payment->state==='verified',422,'Only verified payments may be allocated.');$d=$r->validate(['invoice_id'=>'required|uuid','amount'=>['required','regex:/^\d+(\.\d{1,6})?$/','gt:0']]);$allocation=DB::transaction(function()use($d,$payment){$invoice=SalesInvoice::where('tenant_id',$payment->tenant_id)->whereKey($d['invoice_id'])->lockForUpdate()->firstOrFail();abort_unless($invoice->customer_id===$payment->customer_id,422,'Payment customer does not match invoice customer.');$existing=PaymentAllocation::where('payment_id',$payment->id)->where('invoice_id',$invoice->id)->first();if($existing)return $existing;$allocated=PaymentAllocation::where('payment_id',$payment->id)->sum('amount');$remainingPayment=Decimal::sub((string)$payment->amount,(string)$allocated);$remainingInvoice=Decimal::sub((string)$invoice->total,(string)$invoice->paid_total);$amount=Decimal::normalize((string)$d['amount']);if(Decimal::compare($amount,$remainingPayment)>0||Decimal::compare($amount,$remainingInvoice)>0)throw ValidationException::withMessages(['amount'=>['Allocation exceeds available payment or invoice balance.']]);$a=PaymentAllocation::create(['tenant_id'=>$payment->tenant_id,'payment_id'=>$payment->id,'invoice_id'=>$invoice->id,'amount'=>$amount]);$paid=Decimal::add((string)$invoice->paid_total,$amount);$invoice->update(['paid_total'=>$paid,'state'=>Decimal::compare($paid,(string)$invoice->total)>=0?'paid':'partially_paid']);return $a;});return response()->json(['data'=>$allocation],$allocation->wasRecentlyCreated?201:200);}
 public function print(Request $r,PaymentReceived $payment){$this->authorize($r);$this->own($payment);return response()->view('sales.payment-receipt',['payment'=>$payment->load(['customer','allocations.invoice'])]);}
 private function own(PaymentReceived $p):void{abort_unless($p->tenant_id===$this->tenant(),404);}
}
